(* [comment removed for export] *)
Definition L_SCHED   : list Z := [115; 99; 104; 101; 100; 117; 108; 101; 114].                                    (* [comment removed for export] *)
Definition L_CHINT   : list Z := [99; 111; 110; 99; 117; 114; 114; 101; 110; 99; 121; 95; 104; 105; 110; 116].    (* [comment removed for export] *)
Definition L_LOCKING : list Z := [108; 111; 99; 107; 105; 110; 103].                                              (* [comment removed for export] *)
Definition L_ACONT   : list Z := [97; 115; 115; 117; 109; 101; 95; 99; 111; 110; 116; 105; 110; 117; 97; 116; 105; 111; 110].  (* [comment removed for export] *)
Definition L_SPIN    : list Z := [108; 111; 99; 107; 105; 110; 103; 95; 115; 112; 105; 110; 95; 99; 111; 117; 110; 116].      (* [comment removed for export] *)
Definition L_TASK    : list Z := [116; 97; 115; 107; 95; 117; 115; 101; 99].                                      (* [comment removed for export] *)
Definition L_WAIT    : list Z := [119; 97; 105; 116; 95; 117; 115; 101; 99].                                      (* [comment removed for export] *)
Definition akey_str (k : cfgkey) : list Z :=
  match k with KChint => L_CHINT | KAcont => L_ACONT | KLocking => L_LOCKING | KSpin => L_SPIN | KTask => L_TASK | KWait => L_WAIT end.

Definition GVLITS : list (Z * list Z) :=
  [(AL_STR_SCHEDULER, L_SCHED); (AL_STR_CONCURRENCY_HINT, L_CHINT); (AL_STR_LOCKING, L_LOCKING); (AL_STR_ASSUME_CONT, L_ACONT);
   (AL_STR_SPIN, L_SPIN); (AL_STR_TASK_USEC, L_TASK); (AL_STR_WAIT_USEC, L_WAIT)].

Definition gvlit_okb (AL : Z * list Z) : bool :=
  ro_bytes_b asegs (fst AL) (map b8 (snd AL ++ [0]))
  && aglobb (fst AL) (Z.of_nat (length (snd AL)) + 1)
  && (AIMG_LO + 64 <=? fst AL) && (fst AL + Z.of_nat (length (snd AL)) + 1 + 64 <=? AIMG_TOP)
  && forallb (fun c => (0 <? c) && (c <? 256)) (snd AL).
Lemma GVLITS_ok : forallb gvlit_okb GVLITS = true.
Proof. ltac2:(KReplay.run [|constr:(@Corelib.Init.Logic.eq_refl); constr:(@Corelib.Init.Datatypes.bool); constr:(@Corelib.Init.Datatypes.true); constr:(@Corelib.Init.Logic.eq); constr:(@Stdlib.Lists.List.forallb); constr:(@Corelib.Init.Datatypes.prod); constr:(@Corelib.Numbers.BinNums.Z); constr:(@Corelib.Init.Datatypes.list); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.As.X8_A_gv.gvlit_okb); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.As.X8_A_gv.GVLITS)|] Array.empty "##)###-#'#(#,#&#-#+#*#.#/#)#VFCDUGEVHE#WI#JKWLC#Dm$'##"). Qed.

Lemma akey_in : forall k, In (akey_lit k, akey_str k) GVLITS.
Proof. intros k; destruct k; unfold GVLITS, akey_lit, akey_str; cbn [In]; tauto. Qed.
Lemma sched_in : In (AL_STR_SCHEDULER, L_SCHED) GVLITS. Proof. left. reflexivity. Qed.
Lemma chint_in : In (AL_STR_CONCURRENCY_HINT, L_CHINT) GVLITS. Proof. right; left. reflexivity. Qed.
Lemma locking_in : In (AL_STR_LOCKING, L_LOCKING) GVLITS. Proof. right; right; left. reflexivity. Qed.

