Definition astrcmp_postZ (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (SP r lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra (Z_to_bv 64 SP) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 r) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(SP - 4096, SP)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo SP
    /\ ACONST m'.

Lemma strcmp_glit : strcmp_icpt_stmt ->
  forall (ra gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
         (F : bvmap 5 word) (fc : bv 32) (m : mem) (SP A1 A2 : Z) (L1 L2 : list Z) (lo : Z),
  In (A1, L1) GVLITS -> In (A2, L2) GVLITS ->
  stk asegs m lo SP -> aceil <= lo -> lo <= SP - AINTRIN_STACK -> 0 <= SP < 2^64 ->
  mem_inv asegs m -> ACONST m ->
  evt asegs (astrcmp_postZ ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc SP (zstrcmp L1 L2) lo m)
    (MS (mkR ra (Z_to_bv 64 SP) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 A1) (Z_to_bv 64 A2) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 ASTRCMP_STUB) fc None m (seg_rom asegs)).
