Ltac gv_epilogue SK CAN AW :=
  do 10 step;
  lazymatch goal with ST' : stk _ _ _ (bv_unsigned ?sp + -64), FR' : rw_cells _ _ (bv_unsigned ?sp' + -64) _ |- _ =>
    release_frame FR' ST' (bv_unsigned sp) end;
  finish;
  [ eapply stack0_transport; [exact SK | eassumption | eassumption | eapply Forall_impl; [| exact AW]; intros iv (_ & Kv & _); exact Kv]
  | eapply acanary_transport; [exact CAN | eassumption | eassumption | cbn [disjoint_from]; unfold A_STKCHK_GUARD; unfold AIMG_TOP in *; lia ] ].

